def simulate(obj_cells, H, W, drs, dcs, steps=200):
    # object = set of (r,c) within grid coords
    vel=(1,1); pos=set(obj_cells)
    trail=set()
    seen={}
    for t in range(steps):
        key=(frozenset(pos),vel)
        if key in seen: break
        seen[key]=t
        # check collisions with divider rows/cols (any cell of obj in a divider row/col)
        nr=pos; nv=vel
        coll=False
        if any(r in drs for r,c in pos) or any(c in dcs for r,c in pos):
            # reflect components independently
            rcells=[r for r,c in pos]; ccells=[c for r,c in pos]
            if any(r in drs for r in rcells): vel=( -vel[0], vel[1])
            if any(c in dcs for c in ccells): vel=(vel[0], -vel[1])
            pos={(r, c+vel[1]) if False else (r+vel[0], c)}  # placeholder
        # move
        pos={(r+vel[0], c+vel[1]) for r,c in pos}
        if any(r<0 or r>=H or c<0 or c>=W for r,c in pos):
            # bounce off grid edge
            if any(r==0 for r,c in pos): pos={(r+1,c) for r,c in pos}; vel=(-vel[0],vel[1])
            if any(r==H-1 for r,c in pos): pos={(r-1,c) for r,c in pos}; vel=(-vel[0],vel[1])
            if any(c==0 for r,c in pos): pos={(r,c+1) for r,c in pos}; vel=(vel[0],-vel[1])
            if any(c==W-1 for r,c in pos): pos={(r,c-1) for r,c in pos}; vel=(vel[0],-vel[1])
            if len(pos)<len(obj_cells): break
        trail|=pos
    return trail
