def trans_of(A,B):
    # A,B normalized to origin; check if B equals some transform of A (same size)
    T8={'id':lambda pp:pp,'flipH':lambda pp:(pp[0],-pp[1]),'flipV':lambda pp:(-pp[0],pp[1]),
       'rot90':lambda pp:(pp[1],-pp[0]),'rot180':lambda pp:(-pp[0],-pp[1]),'rot270':lambda pp:(-pp[1],pp[0]),
       'tr':lambda pp:(pp[1],pp[0]),'anti':lambda pp:(-pp[1],-pp[0])}
    for tf,T in T8.items():
        S=frozenset(T(p) for p in A)
        if S==frozenset(B): return tf
    return None
