def f(g):
    H,W=len(g),len(g[0])
    dr,dc=find_divider_sets(g)
    brs=[(a,b) for a,b in zip([-1]+dr,dr+[H])]
    bcs=[(a,b) for a,b in zip([-1]+dc,dc+[W])]
    best=None
    for bi,(r0,r1) in enumerate(brs):
        for bj,(c0,c1) in enumerate(bcs):
            pts=[(r-r0,c-c0) for r in range(r0+1,r1) for c in range(c0+1,c1) if g[r][c]!=0]
            col=g[[r for r in range(r0+1,r1) for c in range(c0+1,c1) if g[r][c]!=0][0]][[c for r in range(r0+1,r1) for c in range(c0+1,c1) if g[r][c]!=0][0]]
            touches=(max(p[1] for p in pts)==c1-2 or max(p[0] for p in pts)==r1-2)
            if not best and touches:
                best=(col,[tuple(sorted(pts))) if False else None
            # record first such block with count of cells
            if touches:
                n=len(pts)
                if best is None or n>best['n']:
                    best={'col':col,'offs':sorted([(p[0],p[1]) for p in pts]),'n':n}
    col,offs=best['col'],best['offs']
    out=[row[:] for row in g]
    for bi,(r0,r1) in enumerate(brs):
        for bj,(c0,c1) in enumerate(bcs):
            # band color from the block's own nonzero color
            col=max([g[r][c] for r in range(r0+1,r1) for c in range(c0+1,c1) if g[r][c]!=0], default=0)
            for dr_,dc_ in offs:
                rr,cc=r0+dr_,c0+dc_
                if 0<=rr<H and 0<=cc<W: out[rr][cc]=col
    for r in dr:
        for c in range(W): out[r][c]=g[r][c]
    for c in dc:
        for r in range(H): out[r][c]=g[r][c]
    return out
